using System;using System.IO;using System.Threading;using SlopProX;
class DeviceIntegrationTests{
 static int Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);int failures=0;DeviceChoice input=null,output=null;foreach(var d in WinMmDevices.AudioInputs())if(d.Name.Contains("Loopback Main"))input=d;foreach(var d in WinMmDevices.AudioOutputs())if(d.Name.Contains("Virtual 7/8"))output=d;
 if(input!=null&&output!=null){string path=Path.Combine(root,"loopback-capture-"+Guid.NewGuid().ToString("N")+".wav");try{WaveCaptureStream capture=new WaveCaptureStream(input.Id,48000,512,path);WaveOutputStream playback=new WaveOutputStream(output.Id,48000,512,delegate(float[] buffer,int frames,long start){for(int i=0;i<frames;i++){float value=(float)(Math.Sin((start+i)*2*Math.PI*440/48000)*0.12);buffer[i*2]=value;buffer[i*2+1]=value;}});Thread.Sleep(900);playback.Dispose();capture.Dispose();if(capture.Error!=null)throw capture.Error;PcmWaveData wave=WaveAudio.Load(path);if(wave.Info.DataBytes<2000)throw new Exception("Input did not preserve sufficient captured PCM data.");double peak=0,sum=0;for(int i=0;i<wave.Samples.Length;i+=2){double v=BitConverter.ToInt16(wave.Samples,i)/32768.0;peak=Math.Max(peak,Math.Abs(v));sum+=v*v;}double rms=Math.Sqrt(sum/(wave.Samples.Length/2));Console.WriteLine("PASS real WinMM loopback device capture: "+input.Name+"; bytes="+wave.Info.DataBytes+"; peak="+peak.ToString("0.000000")+"; RMS="+rms.ToString("0.000000"));Console.WriteLine(peak>0.001?"PASS nonzero audio traveled through the selected virtual output/input route":"NOT VERIFIED injected tone on the selected route: capture contained silence");File.Delete(path);}catch(Exception e){Console.WriteLine("FAIL loopback recording: "+e);failures++;}}
 else Console.WriteLine("NOT RUN physical audio capture: no matching virtual loopback pair available");
 var inputs=WinMmDevices.MidiInputs();if(inputs.Count>1){try{int count=0;using(MidiInputDevice midi=new MidiInputDevice(inputs[1].Id)){midi.MessageReceived+=delegate{Interlocked.Increment(ref count);};Thread.Sleep(120);}Console.WriteLine("PASS real MIDI input open/start/stop/close: "+inputs[1].Name+"; observed events="+count);if(count==0)Console.WriteLine("NOT VERIFIED physical MIDI key events: no keyboard performance was requested");}catch(Exception e){Console.WriteLine("FAIL MIDI device lifecycle: "+e.Message);failures++;}}
 return failures==0?0:1;
 }
}
